import java.util.Scanner;

public class ElectricBill {
    // Instance variables
    private String n;
    private int units;
    private double bill;

    // Method to accept inputs
    public void accept() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Consumer Name: ");
        n = sc.nextLine();
        System.out.print("Enter Units Consumed: ");
        units = sc.nextInt();
    }

    // Method to calculate bill amount based on slab rates
    public void calculate() {
        double charge = 0.0;
        if (units <= 100) {
            charge = units * 2.50;
        } else if (units <= 300) {
            charge = (100 * 2.50) + ((units - 100) * 3.50);
        } else {
            charge = (100 * 2.50) + (200 * 3.50) + ((units - 300) * 4.50);
        }
        // Fixed surcharge of Rs. 150
        bill = charge + 150.0;
    }

    // Method to display consumer details and final bill
    public void print() {
        System.out.println("\n======================================");
        System.out.println("         ELECTRICITY BILL SUMMARY     ");
        System.out.println("======================================");
        System.out.println("Consumer Name      : " + n);
        System.out.println("Units Consumed     : " + units);
        System.out.printf("Total Bill Amount  : Rs. %.2f\n", bill);
        System.out.println("======================================");
    }

    // Main method to instantiate and run
    public static void main(String[] args) {
        ElectricBill obj = new ElectricBill();
        obj.accept();
        obj.calculate();
        obj.print();
    }
}
```

