import java.util.Scanner;

public class BinarySearchDemo {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] arr = new int[15];

        System.out.println("Enter 15 integers in ASCENDING ORDER:");
        for (int i = 0; i < 15; i++) {
            System.out.print("Element " + (i + 1) + ": ");
            arr[i] = sc.nextInt();
        }

        System.out.print("\nEnter the search key: ");
        int key = sc.nextInt();

        // Display array elements
        System.out.print("Array elements: ");
        for (int num : arr) {
            System.out.print(num + " ");
        }
        System.out.println();

        // Binary Search Logic
        int low = 0;
        int high = arr.length - 1;
        int foundIndex = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == key) {
                foundIndex = mid;
                break;
            } else if (arr[mid] < key) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        if (foundIndex != -1) {
            System.out.println("Search Key " + key + " found at index " + foundIndex + " (Position " + (foundIndex + 1) + ").");
        } else {
            System.out.println("Search Key " + key + " not found in the array.");
        }
        sc.close();
    }
}
```

