import java.util.Scanner;

public class StringOperations {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a sentence in UPPERCASE: ");
        String sentence = sc.nextLine().trim().toUpperCase();

        // Operation 1: Count total vowels
        int vowelCount = 0;
        for (int i = 0; i < sentence.length(); i++) {
            char ch = sentence.charAt(i);
            if (ch == 'A' || ch == 'E' || ch == 'I' || ch == 'O' || ch == 'U') {
                vowelCount++;
            }
        }
        System.out.println("Total number of vowels: " + vowelCount);

        // Operation 2: Convert to Title Case
        String[] words = sentence.split("\\s+");
        StringBuilder titleCase = new StringBuilder();

        for (String w : words) {
            if (w.length() > 0) {
                String formatted = w.substring(0, 1).toUpperCase() + w.substring(1).toLowerCase();
                titleCase.append(formatted).append(" ");
            }
        }
        System.out.println("Title Case Sentence: " + titleCase.toString().trim());

        // Operation 3: Identify words with consecutive double letters
        System.out.println("\nWords with consecutive double letters:");
        boolean hasDouble = false;
        for (String w : words) {
            for (int j = 0; j < w.length() - 1; j++) {
                if (w.charAt(j) == w.charAt(j + 1)) {
                    System.out.println("- " + w + " (Repeated letter: '" + w.charAt(j) + "')");
                    hasDouble = true;
                    break;
                }
            }
        }
        if (!hasDouble) {
            System.out.println("None found.");
        }
        sc.close();
    }
}
```

