import java.util.Scanner;

public class TechNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a positive integer: ");
        int num = sc.nextInt();

        // Step 1: Count digits
        int temp = num;
        int digitCount = 0;
        while (temp > 0) {
            digitCount++;
            temp /= 10;
        }

        // Step 2: Validate even number of digits
        if (digitCount % 2 != 0) {
            System.out.println(num + " has " + digitCount + " digits. Number must have an even number of digits.");
        } else {
            // Step 3: Split into two halves
            int divisor = (int) Math.pow(10, digitCount / 2);
            int firstHalf = num / divisor;
            int secondHalf = num % divisor;

            // Step 4: Sum and square
            int sum = firstHalf + secondHalf;
            int squareOfSum = sum * sum;

            System.out.println("First Half   : " + firstHalf);
            System.out.println("Second Half  : " + secondHalf);
            System.out.println("Sum of Halves: " + sum);
            System.out.println("Square of Sum: " + squareOfSum);

            if (squareOfSum == num) {
                System.out.println("\nResult: " + num + " is a TECH NUMBER.");
            } else {
                System.out.println("\nResult: " + num + " is NOT a Tech Number.");
            }
        }
        sc.close();
    }
}
```

