import java.util.Scanner;

public class Matrix4x4Operations {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] mat = new int[4][4];

        System.out.println("Enter elements for a 4 × 4 matrix:");
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                System.out.printf("Element [%d][%d]: ", i, j);
                mat[i][j] = sc.nextInt();
            }
        }

        // 1. Display matrix
        System.out.println("\n--- 4 × 4 Matrix ---");
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                System.out.printf("%6d", mat[i][j]);
            }
            System.out.println();
        }

        // 2. Left & Right Diagonal Sums
        int leftDiagSum = 0;
        int rightDiagSum = 0;
        for (int i = 0; i < 4; i++) {
            leftDiagSum += mat[i][i];         // i == j
            rightDiagSum += mat[i][3 - i];     // i + j == 3
        }

        System.out.println("\nSum of Left Diagonal  (i == j)     : " + leftDiagSum);
        System.out.println("Sum of Right Diagonal (i + j == 3) : " + rightDiagSum);

        // 3. Symmetry Check (mat[i][j] == mat[j][i])
        boolean isSymmetric = true;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (mat[i][j] != mat[j][i]) {
                    isSymmetric = false;
                    break;
                }
            }
            if (!isSymmetric) break;
        }

        System.out.println("\nSymmetry Check: " + (isSymmetric ? "The matrix is SYMMETRIC." : "The matrix is NOT symmetric."));
        sc.close();
    }
}
```

### Variable Description Table (VDT):

| Variable Name | Data Type | Purpose / Description |
| :--- | :--- | :--- |
| `mat` | `int[][]` | 4 × 4 double-dimensional integer array |
| `i` | `int` | Row index counter for matrix traversal |
| `j` | `int` | Column index counter for matrix traversal |
| `leftDiagSum` | `int` | Accumulates sum of principal diagonal elements (`mat[i][i]`) |
| `rightDiagSum` | `int` | Accumulates sum of secondary diagonal elements (`mat[i][3-i]`) |
| `isSymmetric` | `boolean` | Flag initialized to `true`, set to `false` if `mat[i][j] != mat[j][i]` |
